<?php
declare(strict_types=1);require_once __DIR__.'/access.php';require_role('client');$pdo=db();$stmt=$pdo->prepare('SELECT id,name,industry FROM clients WHERE user_id=? AND active=1 LIMIT 1');$stmt->execute([(int)$_SESSION['user']['id']]);$client=$stmt->fetch();$filters=['all','pending','approved','changes_requested'];$filter=in_array($_GET['status']??'all',$filters,true)?(string)($_GET['status']??'all'):'all';$counts=array_fill_keys($filters,0);$content=[];$plans=[];$summary=['posted'=>0,'approval_rate'=>0,'pending_invoices'=>0];
if($client){$q=$pdo->prepare('SELECT status,COUNT(*) total FROM content WHERE client_id=? GROUP BY status');$q->execute([$client['id']]);foreach($q->fetchAll() as $row)$counts[$row['status']]=(int)$row['total'];$counts['all']=array_sum($counts);$from=date('Y-m-01');$to=date('Y-m-d',strtotime($from.' +1 month'));$q=$pdo->prepare("SELECT COUNT(*) posted,SUM(status='approved') approved,SUM(status IN ('approved','changes_requested')) reviewed FROM content WHERE client_id=? AND created_at>=? AND created_at<?");$q->execute([$client['id'],$from,$to]);$monthData=$q->fetch()?:[];$summary['posted']=(int)($monthData['posted']??0);$reviewed=(int)($monthData['reviewed']??0);$summary['approval_rate']=$reviewed?round(((int)$monthData['approved']/$reviewed)*100,1):0;$q=$pdo->prepare('SELECT COALESCE(SUM(pending_amount),0) FROM client_payments WHERE client_id=? AND pending_amount>0');$q->execute([$client['id']]);$summary['pending_invoices']=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT id,title,COALESCE(planned_date,period_start) planned_date,COALESCE(content_type,'static') content_type,notes,goal FROM content_plans WHERE client_id=? AND COALESCE(planned_date,period_start)>=CURDATE() ORDER BY planned_date,id LIMIT 5");$q->execute([$client['id']]);$plans=$q->fetchAll();$sql='SELECT id,title,content_type,status,updated_at FROM content WHERE client_id=?';$params=[$client['id']];if($filter!=='all'){$sql.=' AND status=?';$params[]=$filter;}$sql.=' ORDER BY updated_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$content=$q->fetchAll();}
function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function invoice_amount(float|int|string $v):string{return '₹'.number_format((float)$v,2);}function plan_type(string $v):string{return ucfirst($v==='reel'?'reel':$v);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Dashboard</title><link rel="stylesheet" href="assets/css/saas.css"><style>.upcoming-item{display:flex;gap:12px;align-items:center;border-bottom:1px solid #e2e8f0;padding:11px 0}.upcoming-item:last-child{border-bottom:0}.plan-dot{width:10px;height:10px;border-radius:50%;background:#6366f1;flex:0 0 auto}.plan-dot.reel{background:#f59e0b}.plan-dot.static{background:#22c55e}.plan-dot.carousel{background:#6366f1}</style><script src="assets/js/session-timeout.js" defer></script></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav active" href="client_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav" href="client_content_plan.php">◷ <span>My Plan</span></a><a class="saas-nav" href="content_archive.php">▤ <span>Archive</span></a><a class="saas-nav" href="<?= $client?'view_client_profile.php?client_id='.(int)$client['id']:'#' ?>">♙ <span>My profile</span></a><a class="saas-nav" href="my_invoices.php">▧ <span>Invoices</span></a><div class="nav-label">Account</div><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><header class="saas-topbar"><div><h1 class="saas-title">Client workspace</h1><div class="saas-subtitle">Review your content and track your plan.</div></div><div class="avatar"><?=e(strtoupper(substr($_SESSION['user']['name'],0,1)))?></div></header><?php if(!$client):?><section class="saas-card"><div class="empty-state">Your login is not linked to a client profile yet.</div></section><?php else:?><section class="kpi-grid"><div class="kpi-card"><div class="kpi-label">Content posted this month</div><div class="kpi-value"><?=$summary['posted']?></div></div><div class="kpi-card income"><div class="kpi-label">Approval rate</div><div class="kpi-value"><?=number_format($summary['approval_rate'],1)?>%</div></div><div class="kpi-card expense"><div class="kpi-label">Pending invoices</div><div class="kpi-value"><?=invoice_amount($summary['pending_invoices'])?></div></div><div class="kpi-card"><div class="kpi-label">Upcoming posts</div><div class="kpi-value"><?=count($plans)?></div></div></section><section class="saas-card" style="margin-bottom:16px"><div class="saas-topbar"><h2>Upcoming Posts</h2><a class="btn-outline-indigo" href="client_content_plan.php">View Full Plan</a></div><?php if(!$plans):?><div class="empty-state"><span class="empty-icon">◷</span>No upcoming planned posts.</div><?php else:foreach($plans as $plan):?><div class="upcoming-item"><span class="plan-dot <?=e($plan['content_type'])?>"></span><div><strong><?=e($plan['planned_date'])?></strong><div><?=e(plan_type($plan['content_type']))?> · <?=e($plan['title'])?></div></div></div><?php endforeach;endif;?></section><section class="saas-card" style="margin-bottom:16px"><div class="saas-topbar"><div><h2><?=e($client['name'])?></h2><div class="saas-subtitle"><?=e($client['industry']??'')?></div></div><a class="btn-outline-indigo" href="view_client_profile.php?client_id=<?=$client['id']?>">View brief</a></div></section><section class="saas-card"><div class="d-flex flex-wrap gap-2 mb-3"><?php foreach(['all'=>'All','pending'=>'Pending','approved'=>'Approved','changes_requested'=>'Changes Requested'] as $key=>$label):?><a class="btn <?= $filter===$key?'btn-primary':'btn-outline-primary'?>" href="client_dashboard.php?status=<?=e($key)?>"><?=e($label)?> <span class="badge text-bg-light"><?=$counts[$key]?></span></a><?php endforeach;?></div><h2>Content for review</h2><?php if(!$content):?><div class="empty-state"><span class="empty-icon">◌</span>No content in this filter.</div><?php else:?><div style="overflow:auto"><table class="saas-table"><thead><tr><th>Title</th><th>Type</th><th>Updated</th><th>Status</th></tr></thead><tbody><?php foreach($content as $item):?><tr><td><a href="approve_content.php?content_id=<?=$item['id']?>"><strong><?=e($item['title'])?></strong></a></td><td><?=e(ucfirst($item['content_type']))?></td><td><?=e($item['updated_at'])?></td><td><span class="status-pill status-<?=e($item['status'])?>"><?=e(ucwords(str_replace('_',' ',$item['status'])))?></span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?></main></div></body></html>
